# Read the file to find exact positions for edits
with open('boltons/iterutils.py', 'r') as f:
    lines = f.readlines()

# Find the trace docstring end line
for i, line in enumerate(lines):
    if "or ``'exit'`` to print only the selected events." in line:
        print(f"Trace doc ends at line {i+1}: {line.rstrip()}")
    if "path, registry, stack = (), {}, [(None, root)]" in line:
        print(f"Registry init at line {i+1}: {line.rstrip()}")
    if "elif id_value in registry:" in line:
        print(f"Registry lookup at line {i+1}: {line.rstrip()}")
    if "registry[id_value] = value" in line:
        print(f"Registry store (exit) at line {i+1}: {line.rstrip()}")
    if "registry[id_value] = new_parent" in line:
        print(f"Registry store (enter) at line {i+1}: {line.rstrip()}")
